// Refresh: 25 purane candidates chuno jinki LinkedIn profile 30+ din se check nahi hui
// (Enriched / Talent-pool ready / Contacted ... - Discovered aur Rejected nahi)
const LIMIT = 25, DAYS = 30;
const today = new Date(Date.now() + 5.5 * 3600e3);
const cutoff = new Date(today - DAYS * 864e5).toISOString().slice(0, 10);
const SKIP = /^(discovered|rejected)$/i;
const PRIO = r => /talent|ready|shortlist|contacted|interested/i.test(r.readiness) ? 0 : r.open_to_work === 'Yes' ? 1 : 2;
const take = (node, tab) => $(node).all().map(i => i.json)
  .filter(r => r.linkedin_url && String(r.linkedin_url).includes('linkedin.com/in/') && r.readiness && !SKIP.test(String(r.readiness).trim()))
  .map(r => ({ tab, row: r, checked: String(r.last_checked || r.last_updated || '').slice(0, 10) }))
  .filter(x => !x.checked || x.checked <= cutoff)
  .sort((a, b) => PRIO(a.row) - PRIO(b.row) || a.checked.localeCompare(b.checked));
const sn = take('Read ServiceNow rows', 'ServiceNow'), ai = take('Read AI_ML rows', 'AI_ML');
const picks = [];
while (picks.length < LIMIT && (sn.length || ai.length)) {
  if (sn.length) picks.push(sn.shift());
  if (picks.length < LIMIT && ai.length) picks.push(ai.shift());
}
if (!picks.length) return [];   // abhi koi refresh ke liye due nahi
return [{ json: { picks, urls: picks.map(p => String(p.row.linkedin_url).replace('://in.linkedin.com', '://www.linkedin.com')) } }];

// Refresh: nayi LinkedIn profile ko sheet wale data se milao -> kya badla, kab badla
const picks = $('Pick 25 to refresh').first().json.picks;
const profiles = $input.all().map(i => i.json).filter(p => p && (p.linkedinUrl || p.originalQuery));
const now = new Date(Date.now() + 5.5 * 3600e3);
const today = now.toISOString().slice(0, 10), stamp = now.toISOString().slice(0, 16).replace('T', ' ');
const MON = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
const POOL_RX = { ServiceNow: /service\s?now|\bsnow\b|\bitsm\b|\bitom\b|\bcmdb\b/i,
  AI_ML: /machine learning|\bml\b|\bai\b|artificial intelligence|gen\s?ai|generative|\bllms?\b|data scien|computer vision|\bnlp\b|deep learning|mlops|agentic/i };
const slug = u => (String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i) || [])[1]?.toLowerCase();
const ym = d => d && d.year ? d.year * 12 + (MON[String(d.month || 'jan').slice(0, 3).toLowerCase()] ?? 0) : null;
const nowM = now.getUTCFullYear() * 12 + now.getUTCMonth();
function months(list) {
  const iv = list.filter(([s, e]) => s != null && e != null && e >= s).sort((a, b) => a[0] - b[0]);
  let total = 0, cur = null;
  for (const [s, e] of iv) { if (!cur || s > cur[1]) { if (cur) total += cur[1] - cur[0]; cur = [s, e]; } else cur[1] = Math.max(cur[1], e); }
  if (cur) total += cur[1] - cur[0];
  return total;
}
const yrs = m => Math.round(m / 12 * 10) / 10;
const norm = v => String(v ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
const LABEL = { current_company: 'company', current_title: 'title', city: 'city', open_to_work: 'open_to_work', headline: 'headline' };

const updates = [], changes = [];
let changed = 0, same = 0, failed = 0, gone = 0;
const found = new Set();
for (const p of profiles) {
  const s = slug(p.linkedinUrl) || slug(p.originalQuery && p.originalQuery.query);
  const pk = picks.find(x => slug(x.row.linkedin_url) === s);
  if (!pk || found.has(s)) continue;
  found.add(s);
  const { tab, row: r } = pk;
  const exp = (p.experience || []).map(e => ({ ...e, s: ym(e.startDate), e: /present/i.test(e.endDate?.text || '') || !e.endDate ? nowM : ym(e.endDate) }));
  const cur = exp.find(e => /present/i.test(e.endDate?.text || '') || !e.endDate) || exp[0] || {};
  const loc = String(p.location?.linkedinText || '');
  const fresh = {
    current_company: cur.companyName || '', current_title: cur.position || '',
    city: loc.split(',')[0].trim(), open_to_work: p.openToWork ? 'Yes' : 'No', headline: p.headline || '',
  };
  const upd = { linkedin_url: r.linkedin_url, last_checked: today };
  const diff = [];
  for (const [k, v] of Object.entries(fresh)) {
    const old = r[k] ?? '';
    if (!String(v).trim() || norm(old) === norm(v)) continue;        // naya khaali ya same -> kuch nahi
    upd[k] = v;
    if (!String(old).trim() || /^unknown$/i.test(String(old).trim())) continue;   // pehle khaali tha -> bas bhar do, change nahi
    diff.push(`${LABEL[k]}: ${old} -> ${v}`);
    changes.push({ date: stamp, pool: tab === 'AI_ML' ? 'AI/ML' : 'ServiceNow', name: r.name || p.firstName || '', linkedin_url: r.linkedin_url, field: k, old_value: String(old), new_value: String(v) });
  }
  // experience har baar naya (har mahine badhta hai, change log mein nahi daalte)
  if (exp.length) {
    const calc = yrs(months(exp.map(e => [e.s, e.e])));
    if (calc > Number(r.total_experience_years || 0)) upd.total_experience_years = calc;
    const dom = exp.filter(e => POOL_RX[tab].test(`${e.position || ''} ${e.description || ''} ${(e.skills || []).join(' ')}`));
    if (dom.length) {
      const d = yrs(months(dom.map(e => [e.s, e.e])));
      const dk = tab === 'ServiceNow' ? 'servicenow_experience_years' : 'ai_ml_experience_years';
      if (d > Number(r[dk] || 0)) { upd[dk] = d; upd.experience_bucket = d < 2 ? '0-2' : d < 5 ? '2-5' : d < 8 ? '5-8' : '8+'; }
    }
  }
  const inIndia = p.location?.countryCode === 'IN' || /india/i.test(loc) || (!loc.trim() && !p.location?.countryCode);
  if (!inIndia) {
    diff.push(`moved out of India (${loc.trim()})`);
    upd.readiness = 'Rejected';
    changes.push({ date: stamp, pool: tab === 'AI_ML' ? 'AI/ML' : 'ServiceNow', name: r.name || '', linkedin_url: r.linkedin_url, field: 'readiness', old_value: String(r.readiness || ''), new_value: 'Rejected (not in India)' });
  }
  if (diff.length) {
    changed++;
    upd.last_updated = today;
    upd.last_change = `${today}: ${diff.join('; ')}`;
  } else same++;
  updates.push({ json: { _tab: tab, ...upd } });
}
for (const pk of picks) if (!found.has(slug(pk.row.linkedin_url))) {
  failed++;
  updates.push({ json: { _tab: pk.tab, linkedin_url: pk.row.linkedin_url, last_checked: today,
    notes: `${pk.row.notes || ''}; refresh ${today}: profile nahi mili (private/deleted?)`.replace(/^; /, '') } });
}
const stats = { stamp, requested: picks.length, changed, same, failed, fields: changes.length };
return updates.map((o, i) => (i === 0 ? { json: { ...o.json, _stats: stats, _changes: changes } } : o));

// changes tab ke liye: har badla hua field = 1 row
const ch = $input.first().json._changes || [];
return ch.map(c => ({ json: c }));

const s = $input.first().json._stats;
return [{ json: { 'Run date': s.stamp, 'Flow': 'n8n (refresh)', 'Queries': 0, 'Google results': '', 'LinkedIn profiles found': s.requested,
  'Rejected (not India / wrong title / duplicate)': '', 'New rows added': `${s.changed} changed, ${s.same} same`,
  'Apify cost ($)': Math.round(s.requested * 0.004 * 1000) / 1000,
  'Notes': `Refresh: ${s.fields} field changes logged in "changes" tab. Profile not found: ${s.failed}.` } }];
